// Nest-Egg-Export (CSV oder ZIP) vom Besitzer annehmen, alles andere ignorieren.
// Voraussetzung im Node „Set Tokens“:
//   global.set('nestegg_owner_id', <deine Telegram user_id>);
const orig = msg.originalMessage || {};
const doc = orig.document || {};
const from = orig.from || {};
const owner = global.get('nestegg_owner_id');
const name = doc.file_name || '';

if (!owner) {
    node.status({ fill: 'red', shape: 'ring', text: 'nestegg_owner_id fehlt' });
    node.warn('nestegg_owner_id ist nicht gesetzt – Upload ignoriert');
    return null;
}
if (String(from.id) !== String(owner)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'fremder Absender' });
    return null;
}
if (!/\.(csv|zip)$/i.test(name)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'kein CSV/ZIP: ' + name });
    return null;
}

msg.upload = { chat_id: msg.payload.chatId, user_id: from.id, file_name: name };
node.status({ fill: 'yellow', shape: 'ring', text: name });

// Neuere Bibliotheksversionen liefern den Download-Link schon mit
if (msg.payload.weblink) {
    msg.url = msg.payload.weblink;
    return [msg, null];
}
const fileId = doc.file_id || (typeof msg.payload.content === 'string' ? msg.payload.content : null);
const token = global.get('telegram_token');
msg.url = `https://api.telegram.org/bot${token}/getFile?file_id=${encodeURIComponent(fileId)}`;
return [null, msg];

if (!msg.payload || !msg.payload.ok) {
    throw new Error('getFile fehlgeschlagen: ' + JSON.stringify(msg.payload));
}
const token = global.get('telegram_token');
msg.url = `https://api.telegram.org/file/bot${token}/${msg.payload.result.file_path}`;
return msg;

if (msg.statusCode !== 200 || !Buffer.isBuffer(msg.payload)) {
    throw new Error('Download fehlgeschlagen (HTTP ' + msg.statusCode + ')');
}
// Pfad im Node-RED-Container; überschreibbar per global 'nestegg_upload_path'
msg.filename = global.get('nestegg_upload_path') || '/homeassistant/nestegg/upload/upload.bin';
return msg;

node.status({ fill: 'green', shape: 'dot', text: msg.upload.file_name });
msg.payload = msg.upload;
return msg;

// Fehler im Upload-Zweig → HA-Automation meldet ihn per Telegram
if (!msg.upload) return null;
msg.payload = Object.assign({}, msg.upload, { error: (msg.error && msg.error.message) || 'unbekannter Fehler' });
node.status({ fill: 'red', shape: 'dot', text: msg.payload.error.substring(0, 50) });
return msg;
